#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (ll)1e18;
const int MAXN = 6000;

struct Edge {
    int to, rev;
    ll cap, cost;
};

vector<Edge> g[MAXN];
ll dis[MAXN];
int pv[MAXN], pe[MAXN];
bool ins[MAXN];
int ncnt, src, snk;

void init_graph(int n, int s, int t) {
    for (int i = 0; i <= n; ++i) g[i].clear();
    ncnt = n;
    src = s;
    snk = t;
}

void add_arc(int u, int v, ll cap, ll cost) {
    g[u].push_back({v, (int)g[v].size(), cap, cost});
    g[v].push_back({u, (int)g[u].size() - 1, 0, -cost});
}

ll min_cost_max_flow(ll need) {
    ll ans = 0;
    while (need > 0) {
        fill(dis, dis + ncnt, INF);
        dis[src] = 0;
        deque<int> q;
        q.push_back(src);
        ins[src] = true;
        while (!q.empty()) {
            int u = q.front();
            q.pop_front();
            ins[u] = false;
            for (int i = 0; i < (int)g[u].size(); ++i) {
                Edge &e = g[u][i];
                if (e.cap > 0 && dis[u] + e.cost < dis[e.to]) {
                    dis[e.to] = dis[u] + e.cost;
                    pv[e.to] = u;
                    pe[e.to] = i;
                    if (!ins[e.to]) {
                        ins[e.to] = true;
                        q.push_back(e.to);
                    }
                }
            }
        }
        if (dis[snk] == INF) return -1;
        ll add = need;
        for (int v = snk; v != src; v = pv[v])
            add = min(add, g[pv[v]][pe[v]].cap);
        need -= add;
        ans += add * dis[snk];
        for (int v = snk; v != src; v = pv[v]) {
            Edge &e = g[pv[v]][pe[v]];
            e.cap -= add;
            g[v][e.rev].cap += add;
        }
    }
    return ans;
}

ll N, M, K, C, D;
ll A[58];
vector<int> H[57];

int32_t main() {
    ios::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    cin >> N >> M >> K >> C >> D;
    for (ll i = 1; i <= K; ++i) {
        int x;
        cin >> x;
        A[x]++;
    }
    for (int i = 1; i <= M; ++i) {
        int x, y;
        cin >> x >> y;
        H[x].push_back(y);
        H[y].push_back(x);
    }

    init_graph(5103, 0, 5101);
    for (int i = 2; i <= N; ++i) add_arc(0, i, A[i], 0);
    for (int i = 0; i <= 100; ++i) {
        for (int l = 1; l <= N; ++l) {
            add_arc(50 * i + l, 50 * (i + 1) + l, K, 0);
            for (int j : H[l]) {
                for (ll k = 1; k <= K; ++k) {
                    add_arc(50 * i + l, 50 * (i + 1) + j, 1, D * (2 * k - 1));
                }
            }
        }
    }
    for (int i = 1; i <= 101; ++i) add_arc(50 * i + 1, 5101, K, C * i);
    cout << min_cost_max_flow(K) << endl;
}
